cd /dateutil && python - <<'EOF'
from datetime import datetime, date
from dateutil.relativedelta import relativedelta
cases = [
 dict(months=1.0), dict(years=1.0), dict(years=1.0, months=1.0),
 dict(months=2.0), dict(years=0.0), dict(months=0.0),
 dict(months=-1.0), dict(years=1.0, days=1),
]
for c in cases:
    try:
        rd = relativedelta(**c)
        try:
            r = datetime(2000,1,1)+rd
        except Exception as e:
            r = 'ADD-ERR %s: %s' % (type(e).__name__, e)
        print(c, '->', repr(rd), '|', r)
    except Exception as e:
        print(c, '-> CTOR-ERR', type(e).__name__, e)
EOF

